function update()
    frameTime.sample(ui)
    if titleOpen then drawTitle(); return end
    if familyPhoto.active then
        familyPhoto.tick(frameTime.dt,held(LEFT or 4),held(RIGHT or 2),held(UP or 1),held(DOWN or 3),held(BTN_Z or 4),held(BTN_G or 13))
        if familyPhoto.active then familyPhoto.draw(ui)else previousA,previousB=held(BTN_G or 13),held(BTN_Z or 4)end
        return
    end
    life.tick(animationDelta())
    if life.dead then
        local action=life.input(held(BTN_G or 13),held(BTN_Z or 4))
        if action=='retry'then
            life.reset();enemy.reset();currentRoom='frente';x,y=metric.project('frente',9.7,3.2,0)
            aiming,strike,walking,running=false,0,false,false;crossing=false;transitionCarry=nil;previousA,previousB,previousY=true,true,true
        elseif action=='menu'then titleOpen=true;canContinue=false;return end
    end
    if codeLock.active then
        local a,b,run=held(BTN_G or 13),held(BTN_Z or 4),held(BTN_F or 12)
        local result=codeLock:input({a=a,b=b,up=held(UP or 1),down=held(DOWN or 3),left=held(LEFT or 4),right=held(RIGHT or 2)},frameTime.dt,doors)
        previousA,previousB,previousY=a,b,run
        codeLock:draw(ui)
        if result=='opened'then dialogue:notify('Cadeado aberto.')end
        return
    end
    streetCooldown=math.max(0,streetCooldown-frameTime.dt)
    if pendingStreet then
        -- A frame boundary separates house rendering, release, require and first street draw.
        ui.cls(240);ui.palset(240,0);ui.palset(241,32767)
        ui.print('15.26 - PREPARANDO RUA '..pendingStreet.phase..'/3',95,125,241)
        frameTime.hud(ui)
        if pendingStreet.phase==1 then
            cameras.release();courierCache=nil
            for i=#courierFaces,1,-1 do courierFaces[i]=nil end
            for i=#courierAccepted,1,-1 do courierAccepted[i]=nil end
            for i=#prunedFaces,1,-1 do prunedFaces[i]=nil end
            for key in pairs(overwrittenLines)do overwrittenLines[key]=nil end
            collectgarbage('collect');pendingStreet.phase=2
        elseif pendingStreet.phase==2 then
            local ok,err=pcall(ensureStreet)
            if ok then pendingStreet.phase=3 else
                street=nil;streetMode=false;pendingStreet=nil
                x,y=metric.project('frente',9.7,.8,0);facing=math.pi
                dialogue:notify('Nao foi possivel carregar a rua: '..tostring(err));streetCooldown=2
            end
        else
            street.reset(pendingStreet.x,pendingStreet.y,pendingStreet.angle)
            pendingStreet=nil;collectgarbage('collect')
        end
        return
    end
    if streetMode then
        local a,b=held(BTN_G or 13),held(BTN_Z or 4)
        if a and not previousA then
            if inventory.visible then inventory:back()else inventory:open();inventory.previous.b=b end
        end
        previousA,previousB,previousY=a,b,held(BTN_F or 12)
        if inventory.visible then
            inventory:handle(held(UP or 1),held(DOWN or 3),held(LEFT or 4),held(RIGHT or 2),b,currentRoom,held(inventoryLeftButton),held(inventoryRightButton))
            inventory:draw(bitmapPalette or Palette);return
        end
        local ok,err=pcall(street.update,false,frameTime.dt)
        if not ok then
            streetMode=false;courierCache=nil;streetCooldown=2
            x,y=metric.project('frente',9.7,.8,0);facing=math.pi
            dialogue:notify('Falha ao exibir a rua: '..tostring(err));return
        end
        life.hud(ui);frameTime.hud(ui)
        local sx,sy,sa=street.position()
        if streetCooldown==0 and sx< -4.5 and ((sy>2.65 and sy<3.95)or(sy>6.65 and sy<9.35))then
            streetMode=false;courierCache=nil;currentRoom='frente';x,y=metric.project('frente',sy+6.4,-sx-4.2,0)
            facing=metric.facing('frente',-math.cos(sa),-math.sin(sa));crossing=false;transitionCarry=nil;streetCooldown=1
        end
        return
    end
    ui.cls(0)

    for i, color in ipairs(actorPalette) do ui.palset(actorInk(i-1), color) end
    crowbar.palette(ui)
    local dx = (held(RIGHT or 2) and 1 or 0) - (held(LEFT or 4) and 1 or 0)
    local dy = (held(DOWN or 3) and 1 or 0) - (held(UP or 1) and 1 or 0)
    local a, b = held(BTN_G or 13), held(BTN_Z or 4)
    local run, guard = held(BTN_F or 12), held(BTN_E or 15)
    if life.dead or life.hitTime then dx,dy,a,b,run,guard=0,0,false,false,false,false end
    if life.hitTime then aiming,strike,walking,running=false,0,false,false;queuedStrike=false end
    local cancel, confirm, attack = a and not previousA, b and not previousB, run and not previousY
    previousA, previousB, previousY = a, b, run
    local reading=dialogue.active
    if reading then
        dialogue:handle(confirm,cancel)
        dx,dy,run,guard=0,0,false,false
        confirm,cancel,attack=false,false,false
        aiming,strike=false,0
        transitionCarry=nil
    end
    if not guard then aimCancelled = false end
    if cancel then
        if inventory.visible then
            inventory:back()
        else
            inventory:open()
            transitionCarry=nil
            inventory.previous.b = b
        end
        aiming,strike = false,0
        aimCancelled = guard
    end
    if inventory.visible then
        turning.stop()
        walking,running = false,false
        inventory:handle(held(UP or 1),held(DOWN or 3),held(LEFT or 4),held(RIGHT or 2),b,currentRoom,held(inventoryLeftButton),held(inventoryRightButton))
        inventory:draw(bitmapPalette or Palette)
        return
    end
    local oldStrike=strike
    aiming = guard and not aimCancelled
    if not aiming then
        strike = 0;queuedStrike=false
    elseif attack and strike == 0 then
        strike = 1;queuedStrike=false
    elseif strike > 0 then
        local attackClip=combat.attack(actorClips,inventory.equipped)
        if attack and combat.isBaton(inventory.equipped)and strike>=attackClip.count-7 then queuedStrike=true end
        strike = strike + animationDelta()*(attackClip.fps or 60)
        if strike > attackClip.count then strike=queuedStrike and 1 or 0;queuedStrike=false end
    end
    if strike<=1 or strike<oldStrike then enemyHitThisSwing=false end
    if strike>0 and not enemyHitThisSwing then
        local clip=combat.attack(actorClips,inventory.equipped)
        if strike>=math.floor(clip.count*.35) then
            enemyHitThisSwing=true
            local gx,gy=metric.ground(currentRoom,x,y)
            enemy.tryHit(currentRoom,gx,gy,facing,combat.isBaton(inventory.equipped))
        end
    end
    local inputDx,inputDy=dx,dy
    local throttle=-dy
    local forwardRun=run and throttle>0 and not guard
    local previousFacing=facing
    if not cancel and strike==0 then
        facing=steering.rotate(facing,dx,animationDelta(),aiming,forwardRun)
    end
    if guard or cancel then throttle=0 end
    transitionCarry=nil
    local travelled,worldMoveX,worldMoveY
    if throttle~=0 then
        local wx,wy=steering.forward(currentRoom,facing)
        wx,wy=wx*throttle,wy*throttle
        x,y,travelled,worldMoveX,worldMoveY=perspective.move(currentRoom,x,y,wx,wy,animationDelta(),forwardRun,walkable,true,wx,wy)
    else
        travelled=0
        if dx==0 then crossing=false end
    end
    walking=travelled>0.00001
    running=walking and forwardRun
    local angularDelta=math.atan(math.sin(facing-previousFacing),math.cos(facing-previousFacing))
    turning.tick(dx,not walking and not aiming and strike==0 and not life.dead and not life.hitTime and not cancel,angularDelta)
    if walking then
        local metresPerCycle=running and 3.0118408704 or 1.7576561718
        step=(step+travelled*2*math.pi/metresPerCycle*(throttle<0 and -1 or 1))%(2*math.pi)
    end
    local passageDx,passageDy=0,0
    if worldMoveX then
        local gx,gy=metric.ground(currentRoom,x,y)
        local px,py=metric.project(currentRoom,gx+worldMoveX,gy+worldMoveY,0)
        passageDx,passageDy=px-x,py-y
    end
    checkPassage(passageDx,passageDy,inputDx,inputDy)
    local ix,iy=metric.ground(currentRoom,x,y)
    local interaction=interactions.nearby(currentRoom,ix,iy)
    local nearbyDoor=doors.nearby(currentRoom,ix,iy)
    local status = roomNotice ~= "" and roomNotice or rooms[currentRoom].label
    if aiming then
        status = combat.isBaton(inventory.equipped)and(strike>0 and "GOLPE"or "MACHADINHA")or(strike > 0 and "SOCO" or "PUNHOS LEVANTADOS")
    elseif confirm and not guard and not reading then
        if nearbyDoor then
            local refusal=progression.message(nearbyDoor.id,currentRoom,enemy,doors)
            if refusal then dialogue:notify(refusal)
            elseif nearbyDoor.id=="casinha"then
                codeLock:begin()
            elseif doors.canOpen(nearbyDoor.id,currentRoom,ix,iy)then
                doors.open(nearbyDoor.id);dialogue:notify(nearbyDoor.id=="jardim_quintal"and "Você abriu o portão."or "Você abriu a porta.")
            else dialogue:notify("Afaste-se um pouco da porta.")end
            nearbyDoor=nil
            roomNotice=""
        elseif interaction then
            dialogue:open(interaction.pages)
            facing=perspective.facing(currentRoom,interaction.lookX,interaction.lookY)
            walking,running=false,false
            transitionCarry=nil
        elseif familyPhoto.near(currentRoom,ix,iy)then
            familyPhoto.begin();walking,running,aiming,strike=false,false,false,0
            inventory:collect({id='family_photo',document=true})
        else
            local pickup = inventory:nearby(currentRoom,x,y)
            local result=pickup and inventory:collect(pickup)or "NADA PARA USAR"
            local messages={['ITEM COLETADO']='Item coletado.',['ARQUIVO COLETADO']='Arquivo coletado.',
                ['INVENTARIO CHEIO']='O inventário está cheio.',['NADA PARA USAR']='Não há nada para usar aqui.'}
            dialogue:notify(messages[result]or result)
        end
    end
    local pickup = inventory:nearby(currentRoom,x,y)
    if dialogue.active then
        status=rooms[currentRoom].label
    elseif nearbyDoor and not aiming then
        status=nearbyDoor.id=="casinha"and "B: EXAMINAR CADEADO"or nearbyDoor.id=="garagem_externa"and "B: EXAMINAR PORTA DE ROLO"or nearbyDoor.id=="jardim_quintal"and "B: ABRIR PORTAO"or "B: ABRIR PORTA"
    elseif interaction and not aiming then
        status="B: EXAMINAR QUADROS"
    elseif familyPhoto.near(currentRoom,ix,iy)and not aiming then
        status='B: EXAMINAR FOTO'
    elseif pickup and not aiming then
        status = pickup.document and "B: PEGAR ARQUIVO" or "B: PEGAR ITEM"
    end
    local cgx,cgy=metric.ground(currentRoom,x,y)
    cameras.select(currentRoom,cgx,cgy)
    local strips = cameras.background(currentRoom)or roomBitmaps[currentRoom]
    local native = not not strips
    if native and cameras.enabled and cameras.active then
        cameras.nativePalette(currentRoom,bitmapPalette,ui.palset)
    else
        for i,color in ipairs(native and bitmapPalette or Palette)do ui.palset(i-1,color)end
        if native and metric.rooms[currentRoom]then metric.applyPalette(bitmapPalette,ui.palset,currentRoom);cameras.palette(currentRoom,ui.palset)end
    end
    ui.palset(240,0);ui.palset(241,32767)
    if native then
        for index, strip in ipairs(strips) do
            local ok, result = pcall(ui.spr, strip, 0, (index-1)*(metric.rooms[currentRoom] and 90 or 82))
            if not ok or result == false then
                if currentRoom ~= "sala" then
                    roomBitmaps[currentRoom] = nil
                    currentRoom, x, y, facing = "sala",274.209522014,194.907653768,0
                    status = "ERRO FUNDO: VOLTA A SALA"
                else
                    roomBitmaps.sala, bitmap = nil, nil
                end
                native = false
                ui.cls(0)
                for i, color in ipairs(Palette) do ui.palset(i-1, color) end
                break
            end
        end
    end
    if native then shutter.draw(cameras,currentRoom,ui.spr) end
    local fine = false
    if not native then
        drawImage(detailedBackground, 0, 479)
        fine = fineAvailable and drawFine()
    end
    ui.rectfill(0,0,479,15,240)
    local motion = walking and (running and " / CORRIDA" or " / PASSOS") or ""
    ui.print("15.26 TESTE "..status..motion,8,3,241)
    frameTime.hud(ui)
    if not native and not fine and gridPatches then
        for _, patch in ipairs(gridPatches) do
            if not pcall(ui.grid, patch.x, patch.y, patch.scale, patch.scale, patch.rows) then
                gridPatches = nil
                break
            end
        end
    end
    if currentRoom=='ferramentas'and not inventory.collected.crowbar then crowbar.pickup(cameras,ui)end
    local playerGX,playerGY=metric.ground(currentRoom,x,y)
    enemy.tick(animationDelta(),currentRoom,playerGX,playerGY)
    enemy.palette(ui)
    local enemyBehind=enemy.beforePlayer(currentRoom,x,y)
    if enemyBehind then enemy.draw(currentRoom)end
    courier()
    if not enemyBehind then enemy.draw(currentRoom)end
    if currentRoom==enemy.room then
        ui.rectfill(0,16,245,26,240)
        ui.print('INIMIGO '..(enemy.enabled and ('HP '..enemy.hp..'/'..enemy.maxHp..' '..(enemy.hp<=0 and 'MORTO'or(enemy.attackTime and 'ATAQUE'or 'ON')))or 'OFF'),8,18,241)
    end
    if not cameras.active and currentRoom=="garagem" and carSprite and native then
        local gx,gy=metric.ground(currentRoom,x,y)
        if gy>5.15 then ui.spr(carSprite,metric.carMask.x,metric.carMask.y)end
    end
    if not cameras.active and currentRoom=="sala" then
        local gx,gy=metric.ground(currentRoom,x,y)
        if native and sofaBitmap and gy>3.9 then
            pcall(ui.spr,sofaBitmap,117,121)
        elseif not native and y<=159 then
            drawImage(detailedSofa,x-24,x+24)
        end
    end
    dialogue:tick(animationDelta())
    dialogue:draw(ui)
    if life.dead then
        local set=deathScreen.palette(ui,life)
        if native and cameras.enabled and cameras.active then
            cameras.nativePalette(currentRoom,bitmapPalette,set)
        else
            for i,color in ipairs(native and bitmapPalette or Palette)do set(i-1,color)end
            if native and metric.rooms[currentRoom]then metric.applyPalette(bitmapPalette,set,currentRoom);cameras.palette(currentRoom,set)end
        end
        for i,color in ipairs(actorPalette)do set(actorInk(i-1),color)end
        crowbar.palette(deathScreen.proxy);enemy.palette(deathScreen.proxy)
    end
    life.hud(ui)
    if currentRoom=='frente'and not life.dead and not inventory.visible then
        local gx,gy=metric.ground('frente',x,y)
        if streetCooldown==0 and ((gx>9.15 and gx<10.25)or(gx>13.1 and gx<15.7))and gy<.05 then
            local lx,ly=steering.forward('frente',facing)
            pendingStreet={phase=1,x=-4.2-gy,y=gx-6.4,angle=math.atan(-ly,-lx)}
            streetMode=true;streetCooldown=1
        end
    end
end
